//! Turns a command line into a typed [`Request`], applying the checks of
//! SPEC.md section 2 steps 1 to 3 (shape, required parameters, parameter values).

use crate::error::{Error, ErrorCode, Result};
use serde_json::{Map, Value};
use std::ops::RangeInclusive;

/// Attributes named in a `CreateQueue` or `SetQueueAttributes` request. Only
/// the value checks have run; cross-attribute rules belong to the broker.
#[derive(Debug, Default, PartialEq, Eq)]
pub struct AttributeUpdates {
    pub visibility_timeout: Option<u64>,
    pub delay_seconds: Option<u64>,
    pub retention_seconds: Option<u64>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u64>,
}

#[derive(Debug, PartialEq, Eq)]
pub struct SendMessage {
    pub queue: String,
    pub body: String,
    pub delay_seconds: Option<u64>,
    pub group_id: Option<String>,
    pub deduplication_id: Option<String>,
}

#[derive(Debug, PartialEq, Eq)]
pub enum Request {
    CreateQueue { name: String, attributes: AttributeUpdates },
    SetQueueAttributes { queue: String, attributes: AttributeUpdates },
    GetQueueAttributes { queue: String },
    ListQueues { prefix: Option<String> },
    DeleteQueue { queue: String },
    PurgeQueue { queue: String },
    Tick { seconds: u64 },
    SendMessage(SendMessage),
    ReceiveMessage { queue: String, max_messages: u64, visibility_timeout: Option<u64> },
    DeleteMessage { queue: String, receipt_handle: String },
    ChangeMessageVisibility { queue: String, receipt_handle: String, visibility_timeout: u64 },
}

pub const MAX_VISIBILITY_TIMEOUT: u64 = 43200;
pub const MAX_DELAY_SECONDS: u64 = 900;

/// Parses one input line. Failures are always `InvalidRequest` (step 1) or
/// the parameter errors of steps 2 and 3.
pub fn parse_line(line: &[u8]) -> Result<Request> {
    let invalid = |msg: &str| Error::new(ErrorCode::InvalidRequest, msg);
    let text = std::str::from_utf8(line).map_err(|_| invalid("line is not valid UTF-8"))?;
    let Value::Object(object) =
        serde_json::from_str(text).map_err(|e| invalid(&format!("not valid JSON: {e}")))?
    else {
        return Err(invalid("line is not a JSON object"));
    };
    let Some(Value::String(command)) = object.get("Command") else {
        return Err(invalid("missing string member Command"));
    };
    let f = Fields(&object);
    match command.as_str() {
        "CreateQueue" => {
            let name = f.require("QueueName")?;
            // The name is checked before every other parameter.
            let name = string(name, "QueueName")?;
            if !is_valid_queue_name(name) {
                return Err(Error::new(
                    ErrorCode::QueueNameInvalid,
                    format!("{name:?} breaks the queue naming rules"),
                ));
            }
            let attributes = match f.get("Attributes") {
                Some(v) => attribute_updates(v)?,
                None => AttributeUpdates::default(),
            };
            Ok(Request::CreateQueue { name: name.to_owned(), attributes })
        }
        "SetQueueAttributes" => {
            let (queue, attributes) = (f.require("QueueName")?, f.require("Attributes")?);
            Ok(Request::SetQueueAttributes {
                queue: string(queue, "QueueName")?.to_owned(),
                attributes: attribute_updates(attributes)?,
            })
        }
        "GetQueueAttributes" => Ok(Request::GetQueueAttributes { queue: f.queue_name()? }),
        "ListQueues" => Ok(Request::ListQueues {
            prefix: f.get("Prefix").map(|v| string(v, "Prefix").map(str::to_owned)).transpose()?,
        }),
        "DeleteQueue" => Ok(Request::DeleteQueue { queue: f.queue_name()? }),
        "PurgeQueue" => Ok(Request::PurgeQueue { queue: f.queue_name()? }),
        "Tick" => {
            let seconds = f.require("Seconds")?;
            Ok(Request::Tick { seconds: integer(seconds, "Seconds", 0..=1_209_600)? })
        }
        "SendMessage" => {
            let (queue, body) = (f.require("QueueName")?, f.require("Body")?);
            let queue = string(queue, "QueueName")?.to_owned();
            let body = string(body, "Body")?;
            if !(1..=1024).contains(&body.len()) {
                return Err(bad_value("Body must be 1 to 1024 bytes"));
            }
            Ok(Request::SendMessage(SendMessage {
                queue,
                body: body.to_owned(),
                delay_seconds: f.optional_integer("DelaySeconds", 0..=MAX_DELAY_SECONDS)?,
                group_id: f.optional_id("GroupId")?,
                deduplication_id: f.optional_id("DeduplicationId")?,
            }))
        }
        "ReceiveMessage" => {
            let queue = f.queue_name()?;
            Ok(Request::ReceiveMessage {
                queue,
                max_messages: f.optional_integer("MaxMessages", 1..=10)?.unwrap_or(1),
                visibility_timeout: f
                    .optional_integer("VisibilityTimeout", 0..=MAX_VISIBILITY_TIMEOUT)?,
            })
        }
        "DeleteMessage" => {
            let (queue, handle) = f.queue_and_handle()?;
            Ok(Request::DeleteMessage { queue, receipt_handle: handle })
        }
        "ChangeMessageVisibility" => {
            let timeout = f.require("VisibilityTimeout");
            let (queue, handle) = f.queue_and_handle_required(timeout.as_ref().err())?;
            let timeout = integer(timeout?, "VisibilityTimeout", 0..=MAX_VISIBILITY_TIMEOUT)?;
            Ok(Request::ChangeMessageVisibility {
                queue,
                receipt_handle: handle,
                visibility_timeout: timeout,
            })
        }
        other => Err(invalid(&format!("unknown command {other:?}"))),
    }
}

/// Name syntax of SPEC.md section 4.
pub fn is_valid_queue_name(name: &str) -> bool {
    let plain = |s: &str| s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
    match name.strip_suffix(".fifo") {
        Some(stem) => (1..=75).contains(&stem.chars().count()) && plain(stem),
        None => (1..=80).contains(&name.chars().count()) && plain(name),
    }
}

fn bad_value(message: impl Into<String>) -> Error {
    Error::new(ErrorCode::InvalidParameterValue, message)
}

fn string<'a>(value: &'a Value, name: &str) -> Result<&'a str> {
    value.as_str().ok_or_else(|| bad_value(format!("{name} must be a string")))
}

/// Accepts only JSON numbers written as integers (`as_i64` is `None` for `30.0`).
fn integer(value: &Value, name: &str, range: RangeInclusive<u64>) -> Result<u64> {
    value
        .as_i64()
        .and_then(|n| u64::try_from(n).ok())
        .filter(|n| range.contains(n))
        .ok_or_else(|| {
            bad_value(format!("{name} must be an integer from {} to {}", range.start(), range.end()))
        })
}

fn boolean(value: &Value, name: &str) -> Result<bool> {
    value.as_bool().ok_or_else(|| bad_value(format!("{name} must be a boolean")))
}

fn attribute_updates(value: &Value) -> Result<AttributeUpdates> {
    let Value::Object(map) = value else {
        return Err(bad_value("Attributes must be an object"));
    };
    let mut updates = AttributeUpdates::default();
    for (name, value) in map {
        if value.is_null() {
            // Null means absent, but the name must still be one we know.
            if !ATTRIBUTE_NAMES.contains(&name.as_str()) {
                return Err(bad_value(format!("unknown attribute {name:?}")));
            }
            continue;
        }
        match name.as_str() {
            "VisibilityTimeout" => {
                updates.visibility_timeout =
                    Some(integer(value, name, 0..=MAX_VISIBILITY_TIMEOUT)?)
            }
            "DelaySeconds" => {
                updates.delay_seconds = Some(integer(value, name, 0..=MAX_DELAY_SECONDS)?)
            }
            "RetentionSeconds" => {
                updates.retention_seconds = Some(integer(value, name, 60..=1_209_600)?)
            }
            "Fifo" => updates.fifo = Some(boolean(value, name)?),
            "ContentBasedDeduplication" => {
                updates.content_based_deduplication = Some(boolean(value, name)?)
            }
            "DeadLetterQueue" => updates.dead_letter_queue = Some(string(value, name)?.to_owned()),
            "MaxReceiveCount" => updates.max_receive_count = Some(integer(value, name, 1..=1000)?),
            _ => return Err(bad_value(format!("unknown attribute {name:?}"))),
        }
    }
    Ok(updates)
}

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

/// Read access to a command's members, where `null` counts as absent.
struct Fields<'a>(&'a Map<String, Value>);

impl Fields<'_> {
    fn get(&self, name: &str) -> Option<&Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    fn require(&self, name: &str) -> Result<&Value> {
        self.get(name).ok_or_else(|| {
            Error::new(ErrorCode::MissingParameter, format!("{name} is required"))
        })
    }

    fn queue_name(&self) -> Result<String> {
        Ok(string(self.require("QueueName")?, "QueueName")?.to_owned())
    }

    fn optional_integer(&self, name: &str, range: RangeInclusive<u64>) -> Result<Option<u64>> {
        self.get(name).map(|v| integer(v, name, range)).transpose()
    }

    /// `GroupId` / `DeduplicationId`: 1 to 128 characters from `A-Z a-z 0-9 _ -`.
    fn optional_id(&self, name: &str) -> Result<Option<String>> {
        let Some(value) = self.get(name) else { return Ok(None) };
        let id = string(value, name)?;
        let valid = (1..=128).contains(&id.chars().count())
            && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
        if valid { Ok(Some(id.to_owned())) } else { Err(bad_value(format!("{name} is not valid"))) }
    }

    fn queue_and_handle(&self) -> Result<(String, String)> {
        self.queue_and_handle_required(None)
    }

    /// Both members are required before any value is checked; `also_missing`
    /// carries an earlier required-parameter failure of the same command.
    fn queue_and_handle_required(&self, also_missing: Option<&Error>) -> Result<(String, String)> {
        let (queue, handle) = (self.require("QueueName"), self.require("ReceiptHandle"));
        let (queue, handle) = (queue?, handle?);
        if let Some(e) = also_missing {
            return Err(Error::new(e.code, e.message.clone()));
        }
        Ok((
            string(queue, "QueueName")?.to_owned(),
            string(handle, "ReceiptHandle")?.to_owned(),
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn code(line: &str) -> ErrorCode {
        parse_line(line.as_bytes()).unwrap_err().code
    }

    #[test]
    fn shape_errors_are_invalid_request() {
        for line in ["", "[]", "{", r#"{"Command": 1}"#, r#"{"Command":"Nope"}"#, "{} x"] {
            assert_eq!(code(line), ErrorCode::InvalidRequest, "{line}");
        }
        assert_eq!(parse_line(b"{\"Command\":\"Tick\",\"Seconds\":\xff}").unwrap_err().code,
            ErrorCode::InvalidRequest);
    }

    #[test]
    fn integers_must_be_written_as_integers() {
        for bad in ["30.0", "3e1", "\"30\"", "-1", "1209601"] {
            let line = format!(r#"{{"Command":"Tick","Seconds":{bad}}}"#);
            assert_eq!(code(&line), ErrorCode::InvalidParameterValue, "{bad}");
        }
        let ok = parse_line(br#"{"Command":"Tick","Seconds":30}"#).unwrap();
        assert_eq!(ok, Request::Tick { seconds: 30 });
    }

    #[test]
    fn missing_beats_wrong_type_and_null_is_absent() {
        let line = r#"{"Command":"DeleteMessage","QueueName":5,"ReceiptHandle":null}"#;
        assert_eq!(code(line), ErrorCode::MissingParameter);
        let line = r#"{"Command":"ReceiveMessage","QueueName":"q","MaxMessages":null}"#;
        assert!(matches!(
            parse_line(line.as_bytes()),
            Ok(Request::ReceiveMessage { max_messages: 1, .. })
        ));
    }

    #[test]
    fn create_queue_checks_the_name_first() {
        let line = r#"{"Command":"CreateQueue","QueueName":"a b","Attributes":5}"#;
        assert_eq!(code(line), ErrorCode::QueueNameInvalid);
        let line = r#"{"Command":"CreateQueue","QueueName":"ab","Attributes":{"Bogus":1}}"#;
        assert_eq!(code(line), ErrorCode::InvalidParameterValue);
    }

    #[test]
    fn queue_name_syntax() {
        assert!(is_valid_queue_name("jobs-1_x"));
        assert!(is_valid_queue_name(&format!("{}.fifo", "a".repeat(75))));
        assert!(!is_valid_queue_name(&format!("{}.fifo", "a".repeat(76))));
        assert!(is_valid_queue_name(&"a".repeat(80)));
        assert!(!is_valid_queue_name(&"a".repeat(81)));
        assert!(!is_valid_queue_name(".fifo"));
        assert!(!is_valid_queue_name(""));
        assert!(!is_valid_queue_name("a.b"));
    }
}
