//! One queue: its attributes, messages in arrival order, and deduplication log.

use std::collections::{BTreeMap, HashMap};

pub const MAX_MESSAGES: usize = 100_000;
pub const DEDUP_WINDOW: u64 = 300;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: u64,
    pub delay_seconds: u64,
    pub retention_seconds: u64,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

/// Why a message is not visible. Which one applies only matters while
/// `hidden_until` lies in the future.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Hidden {
    Delayed,
    InFlight,
}

#[derive(Clone, Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u64,
    pub first_received_at: Option<u64>,
    pub group_id: Option<String>,
    pub sequence_number: Option<u64>,
    pub hidden_until: u64,
    pub hidden: Hidden,
    /// Number `n` of the latest `r-<n>` handle issued for this message.
    pub latest_handle: Option<u64>,
}

impl Message {
    pub fn is_visible(&self, now: u64) -> bool {
        now >= self.hidden_until
    }

    pub fn is_in_flight(&self, now: u64) -> bool {
        !self.is_visible(now) && self.hidden == Hidden::InFlight
    }
}

/// The original send behind a deduplication id.
#[derive(Clone, Copy, Debug)]
pub struct DedupEntry {
    pub accepted_at: u64,
    pub message_id: u64,
    pub sequence_number: u64,
}

#[derive(Debug)]
pub struct Queue {
    /// Distinguishes this queue from an earlier one of the same name.
    pub id: u64,
    pub attributes: Attributes,
    /// Keyed by arrival key, which only grows, so iteration is arrival order.
    pub messages: BTreeMap<u64, Message>,
    pub dedup: HashMap<String, DedupEntry>,
    next_key: u64,
    next_sequence: u64,
    /// Lower bound of `sent_at` over `messages`, so retention can skip the
    /// scan when nothing can have expired yet.
    oldest_sent_at: u64,
}

impl Queue {
    pub fn new(id: u64, attributes: Attributes) -> Self {
        Self {
            id,
            attributes,
            messages: BTreeMap::new(),
            dedup: HashMap::new(),
            next_key: 0,
            next_sequence: 1,
            oldest_sent_at: u64::MAX,
        }
    }

    /// Adds `message` at the end; returns its arrival key.
    pub fn push(&mut self, mut message: Message) -> u64 {
        if self.attributes.fifo {
            message.sequence_number = Some(self.next_sequence);
            self.next_sequence += 1;
        }
        self.oldest_sent_at = self.oldest_sent_at.min(message.sent_at);
        let key = self.next_key;
        self.next_key += 1;
        self.messages.insert(key, message);
        key
    }

    /// Removes every message whose retention has run out at `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = self.attributes.retention_seconds;
        if now < self.oldest_sent_at.saturating_add(retention) {
            return;
        }
        self.messages.retain(|_, m| now < m.sent_at + retention);
        self.oldest_sent_at = self.messages.values().map(|m| m.sent_at).min().unwrap_or(u64::MAX);
    }

    /// Counts of (visible, in flight, delayed) messages.
    pub fn counts(&self, now: u64) -> (usize, usize, usize) {
        let mut counts = (0, 0, 0);
        for m in self.messages.values() {
            if m.is_visible(now) {
                counts.0 += 1;
            } else if m.hidden == Hidden::InFlight {
                counts.1 += 1;
            } else {
                counts.2 += 1;
            }
        }
        counts
    }
}
