//! All process state and the execution of parsed requests.

use crate::error::{Error, ErrorCode, Result};
use crate::queue::{
    Attributes, DEDUP_WINDOW, DeadLetter, DedupEntry, Hidden, MAX_MESSAGES, Message, Queue,
};
use crate::request::{AttributeUpdates, Request, SendMessage};
use serde_json::{Map, Value, json};
use std::collections::{BTreeMap, HashSet};

const MAX_QUEUES: usize = 1000;

#[derive(Default)]
pub struct Broker {
    now: u64,
    queues: BTreeMap<String, Queue>,
    next_queue_id: u64,
    last_message_id: u64,
    /// `(queue id, arrival key)` of every delivery; handle `r-n` is entry `n - 1`.
    handles: Vec<(u64, u64)>,
}

fn err<T>(code: ErrorCode, message: impl Into<String>) -> Result<T> {
    Err(Error::new(code, message))
}

impl Broker {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs a request and returns the result members of a success.
    pub fn execute(&mut self, request: Request) -> Result<Map<String, Value>> {
        let result = match request {
            Request::CreateQueue { name, attributes } => self.create_queue(name, attributes)?,
            Request::SetQueueAttributes { queue, attributes } => {
                self.set_queue_attributes(&queue, attributes)?
            }
            Request::GetQueueAttributes { queue } => self.get_queue_attributes(&queue)?,
            Request::ListQueues { prefix } => {
                let prefix = prefix.unwrap_or_default();
                let names: Vec<_> = self.queues.keys().filter(|n| n.starts_with(&prefix)).collect();
                json!({ "QueueNames": names })
            }
            Request::DeleteQueue { queue } => self.delete_queue(&queue)?,
            Request::PurgeQueue { queue } => {
                self.queue_mut(&queue)?.messages.clear();
                json!({})
            }
            Request::Tick { seconds } => {
                self.now += seconds;
                json!({ "Now": self.now })
            }
            Request::SendMessage(send) => self.send_message(send)?,
            Request::ReceiveMessage { queue, max_messages, visibility_timeout } => {
                self.receive_message(&queue, max_messages, visibility_timeout)?
            }
            Request::DeleteMessage { queue, receipt_handle } => {
                let (q, key) = self.in_flight(&queue, &receipt_handle)?;
                q.messages.remove(&key);
                json!({})
            }
            Request::ChangeMessageVisibility { queue, receipt_handle, visibility_timeout } => {
                let now = self.now;
                let (q, key) = self.in_flight(&queue, &receipt_handle)?;
                if let Some(m) = q.messages.get_mut(&key) {
                    m.hidden_until = now + visibility_timeout;
                }
                json!({})
            }
        };
        match result {
            Value::Object(members) => Ok(members),
            _ => unreachable!("results are built as JSON objects"),
        }
    }

    /// Looks a queue up, first applying retention so callers see only live messages.
    fn queue_mut(&mut self, name: &str) -> Result<&mut Queue> {
        let now = self.now;
        match self.queues.get_mut(name) {
            Some(queue) => {
                queue.expire(now);
                Ok(queue)
            }
            None => err(ErrorCode::QueueDoesNotExist, format!("no queue named {name:?}")),
        }
    }

    fn create_queue(&mut self, name: String, updates: AttributeUpdates) -> Result<Value> {
        let fifo = updates.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return err(ErrorCode::QueueNameInvalid, "a queue is FIFO exactly when its name ends in .fifo");
        }
        let cbd = updates.content_based_deduplication.unwrap_or(false);
        if cbd && !fifo {
            return err(ErrorCode::InvalidParameterValue, "ContentBasedDeduplication needs a FIFO queue");
        }
        let dead_letter = dead_letter_of(&updates)?;
        let defaults = Attributes::default();
        let attributes = Attributes {
            visibility_timeout: updates.visibility_timeout.unwrap_or(defaults.visibility_timeout),
            delay_seconds: updates.delay_seconds.unwrap_or(defaults.delay_seconds),
            retention_seconds: updates.retention_seconds.unwrap_or(defaults.retention_seconds),
            fifo,
            content_based_deduplication: cbd,
            dead_letter,
        };
        if let Some(existing) = self.queues.get(&name) {
            return if existing.attributes == attributes {
                Ok(json!({}))
            } else {
                err(ErrorCode::QueueAlreadyExists, format!("queue {name:?} exists with other attributes"))
            };
        }
        if let Some(dead_letter) = &attributes.dead_letter {
            let Some(target) = self.queues.get(&dead_letter.queue) else {
                return err(ErrorCode::QueueDoesNotExist, "the dead-letter queue does not exist");
            };
            if target.attributes.fifo != fifo {
                return err(ErrorCode::InvalidParameterValue, "dead-letter queue must have the same Fifo");
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return err(ErrorCode::LimitExceeded, "1000 queues already exist");
        }
        self.next_queue_id += 1;
        self.queues.insert(name, Queue::new(self.next_queue_id, attributes));
        Ok(json!({}))
    }

    fn set_queue_attributes(&mut self, name: &str, updates: AttributeUpdates) -> Result<Value> {
        let queue = self.queue_mut(name)?;
        let fifo = queue.attributes.fifo;
        if updates.fifo.is_some() {
            return err(ErrorCode::UnsupportedOperation, "the type of a queue never changes");
        }
        if updates.content_based_deduplication == Some(true) && !fifo {
            return err(ErrorCode::InvalidParameterValue, "ContentBasedDeduplication needs a FIFO queue");
        }
        let dead_letter = dead_letter_of(&updates)?;
        if let Some(dead_letter) = &dead_letter {
            let Some(target) = self.queues.get(&dead_letter.queue) else {
                return err(ErrorCode::QueueDoesNotExist, "the dead-letter queue does not exist");
            };
            if dead_letter.queue == name || target.attributes.fifo != fifo {
                return err(ErrorCode::InvalidParameterValue, "invalid dead-letter queue");
            }
        }
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let a = &mut queue.attributes;
        a.visibility_timeout = updates.visibility_timeout.unwrap_or(a.visibility_timeout);
        a.delay_seconds = updates.delay_seconds.unwrap_or(a.delay_seconds);
        a.retention_seconds = updates.retention_seconds.unwrap_or(a.retention_seconds);
        a.content_based_deduplication =
            updates.content_based_deduplication.unwrap_or(a.content_based_deduplication);
        if dead_letter.is_some() {
            a.dead_letter = dead_letter;
        }
        queue.expire(now);
        Ok(json!({}))
    }

    fn get_queue_attributes(&mut self, name: &str) -> Result<Value> {
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let a = &queue.attributes;
        let mut attributes = json!({
            "VisibilityTimeout": a.visibility_timeout,
            "DelaySeconds": a.delay_seconds,
            "RetentionSeconds": a.retention_seconds,
            "Fifo": a.fifo,
            "ContentBasedDeduplication": a.content_based_deduplication,
        });
        if let Some(d) = &a.dead_letter {
            attributes["DeadLetterQueue"] = json!(d.queue);
            attributes["MaxReceiveCount"] = json!(d.max_receive_count);
        }
        let (visible, in_flight, delayed) = queue.counts(now);
        Ok(json!({
            "Attributes": attributes,
            "Counts": { "Visible": visible, "InFlight": in_flight, "Delayed": delayed },
        }))
    }

    fn delete_queue(&mut self, name: &str) -> Result<Value> {
        self.queue_mut(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.attributes.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.attributes.dead_letter = None;
            }
        }
        Ok(json!({}))
    }

    fn send_message(&mut self, send: SendMessage) -> Result<Value> {
        let now = self.now;
        let queue = self.queue_mut(&send.queue)?;
        let fifo = queue.attributes.fifo;
        if (!fifo && (send.group_id.is_some() || send.deduplication_id.is_some()))
            || (fifo && send.delay_seconds.is_some())
        {
            return err(ErrorCode::UnsupportedOperation, "not supported by this type of queue");
        }
        let mut dedup_id = None;
        if fifo {
            if send.group_id.is_none() {
                return err(ErrorCode::MissingParameter, "GroupId is required on a FIFO queue");
            }
            if send.deduplication_id.is_none() && !queue.attributes.content_based_deduplication {
                return err(ErrorCode::MissingParameter, "DeduplicationId is required");
            }
            let id = send.deduplication_id.clone().unwrap_or_else(|| send.body.clone());
            if let Some(original) = queue.dedup.get(&id).filter(|e| now - e.accepted_at < DEDUP_WINDOW) {
                return Ok(json!({
                    "MessageId": format!("m-{}", original.message_id),
                    "SequenceNumber": original.sequence_number,
                }));
            }
            dedup_id = Some(id);
        }
        if queue.messages.len() >= MAX_MESSAGES {
            return err(ErrorCode::LimitExceeded, "the queue holds 100000 messages");
        }
        let delay = send.delay_seconds.unwrap_or(queue.attributes.delay_seconds);
        self.last_message_id += 1;
        let id = self.last_message_id;
        let key = queue.push(Message {
            id,
            body: send.body,
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group_id: send.group_id,
            sequence_number: None,
            hidden_until: now + delay,
            hidden: Hidden::Delayed,
            latest_handle: None,
        });
        let sequence_number = queue.messages[&key].sequence_number;
        if let (Some(id), Some(sequence_number)) = (dedup_id, sequence_number) {
            queue.dedup.insert(id, DedupEntry { accepted_at: now, message_id: self.last_message_id, sequence_number });
        }
        let mut result = json!({ "MessageId": format!("m-{id}") });
        if let Some(sequence_number) = sequence_number {
            result["SequenceNumber"] = json!(sequence_number);
        }
        Ok(result)
    }

    fn receive_message(&mut self, name: &str, max: u64, timeout: Option<u64>) -> Result<Value> {
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let timeout = timeout.unwrap_or(queue.attributes.visibility_timeout);
        let dead_letter = queue.attributes.dead_letter.clone();
        let mut delivered = Vec::new();
        let mut moved = Vec::new();
        // Groups that still have an earlier message in this queue.
        let mut occupied_groups = HashSet::new();
        for (&key, message) in queue.messages.iter_mut() {
            if delivered.len() as u64 >= max {
                break;
            }
            let blocked = message.group_id.as_ref().is_some_and(|g| occupied_groups.contains(g));
            if !blocked && message.is_visible(now) {
                if dead_letter.as_ref().is_some_and(|d| message.receive_count >= d.max_receive_count) {
                    // Leaves the queue, so it does not block its group.
                    moved.push(key);
                    continue;
                }
                message.receive_count += 1;
                message.first_received_at.get_or_insert(now);
                message.hidden_until = now + timeout;
                message.hidden = Hidden::InFlight;
                self.handles.push((queue.id, key));
                let handle = self.handles.len() as u64;
                message.latest_handle = Some(handle);
                let mut out = json!({
                    "MessageId": format!("m-{}", message.id),
                    "ReceiptHandle": format!("r-{handle}"),
                    "Body": message.body,
                    "ReceiveCount": message.receive_count,
                    "SentAt": message.sent_at,
                    "FirstReceivedAt": message.first_received_at,
                });
                if let (Some(group), Some(seq)) = (&message.group_id, message.sequence_number) {
                    out["GroupId"] = json!(group);
                    out["SequenceNumber"] = json!(seq);
                }
                delivered.push(out);
            }
            if let (false, Some(group)) = (blocked, &message.group_id) {
                occupied_groups.insert(group.clone());
            }
        }
        if let Some(dead_letter) = dead_letter {
            let moved: Vec<Message> =
                moved.iter().filter_map(|key| queue.messages.remove(key)).collect();
            self.move_to_dead_letter(&dead_letter, moved);
        }
        Ok(json!({ "Messages": delivered }))
    }

    fn move_to_dead_letter(&mut self, dead_letter: &DeadLetter, moved: Vec<Message>) {
        let now = self.now;
        let Some(target) = self.queues.get_mut(&dead_letter.queue) else {
            unreachable!("deleting a queue clears every dead-letter reference to it");
        };
        for message in moved {
            target.push(Message {
                receive_count: 0,
                first_received_at: None,
                hidden_until: now,
                hidden: Hidden::Delayed,
                latest_handle: None,
                sequence_number: None,
                ..message
            });
        }
        target.expire(now);
    }

    /// Finds the message a handle refers to, which must be in flight right now.
    fn in_flight(&mut self, queue: &str, handle: &str) -> Result<(&mut Queue, u64)> {
        let now = self.now;
        let issued = self.handles.len() as u64;
        let handles = std::mem::take(&mut self.handles);
        let result = self.queue_mut(queue).and_then(|q| {
            let Some(n) = parse_handle(handle).filter(|&n| n <= issued) else {
                return err(ErrorCode::ReceiptHandleInvalid, "this handle was never issued");
            };
            let (queue_id, key) = handles[n as usize - 1];
            let live = queue_id == q.id
                && q.messages.get(&key).is_some_and(|m| m.latest_handle == Some(n) && m.is_in_flight(now));
            if live {
                Ok(key)
            } else {
                err(ErrorCode::ReceiptHandleExpired, "this handle is no longer usable")
            }
        });
        self.handles = handles;
        let key = result?;
        Ok((self.queues.get_mut(queue).expect("looked up above"), key))
    }
}

/// `r-<n>` with `n` written in canonical decimal form and at least 1.
fn parse_handle(handle: &str) -> Option<u64> {
    let digits = handle.strip_prefix("r-")?;
    let canonical = !digits.starts_with('0') && digits.bytes().all(|b| b.is_ascii_digit());
    if canonical { digits.parse().ok() } else { None }
}

/// The pair `DeadLetterQueue`/`MaxReceiveCount` must be given together.
fn dead_letter_of(updates: &AttributeUpdates) -> Result<Option<DeadLetter>> {
    match (&updates.dead_letter_queue, updates.max_receive_count) {
        (Some(queue), Some(max_receive_count)) => {
            Ok(Some(DeadLetter { queue: queue.clone(), max_receive_count }))
        }
        (None, None) => Ok(None),
        _ => err(ErrorCode::InvalidParameterValue, "DeadLetterQueue and MaxReceiveCount go together"),
    }
}
