//! miniq: a small in-memory message queue driven by JSON lines (see SPEC.md).

mod broker;
mod error;
mod queue;
mod request;

use broker::Broker;
use serde_json::{Map, Value, json};
use std::io::{self, BufRead, Write};

/// Answers every line of `input` with one JSON line on `output`, flushing
/// after each so a client can interleave requests and responses.
pub fn run(mut input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let mut broker = Broker::new();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let response = match request::parse_line(&line).and_then(|r| broker.execute(r)) {
            Ok(mut members) => {
                members.insert("ok".to_owned(), Value::Bool(true));
                Value::Object(members)
            }
            Err(e) => json!({
                "ok": false,
                "error": { "code": e.code.as_str(), "message": e.message },
            }),
        };
        serde_json::to_writer(&mut output, &response)?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}

