mkdir -p tests && cat > tests/protocol.rs <<'EOF'
use serde_json::{Value, json};
use std::io::Write;
use std::process::{Command, Stdio};

fn run(lines: &[&str]) -> Vec<Value> {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    let input = lines.join("\n") + "\n";
    child.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();
    let out = child.wait_with_output().unwrap();
    assert!(out.status.success());
    String::from_utf8(out.stdout).unwrap().lines().map(|l| serde_json::from_str(l).unwrap()).collect()
}

#[test]
fn every_line_gets_one_response() {
    let r = run(&["", "nope", r#"{"Command":"Tick","Seconds":5}"#]);
    assert_eq!(r[0]["error"]["code"], "InvalidRequest");
    assert_eq!(r[1]["error"]["code"], "InvalidRequest");
    assert_eq!(r[2], json!({"ok": true, "Now": 5}));
}

#[test]
fn visibility_timeout_redelivers_and_invalidates_old_handle() {
    let r = run(&[
        r#"{"Command":"CreateQueue","QueueName":"q","Attributes":{"VisibilityTimeout":10}}"#,
        r#"{"Command":"SendMessage","QueueName":"q","Body":"hi"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"q"}"#,
        r#"{"Command":"Tick","Seconds":10}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"q"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"r-1"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"r-01"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"r-2"}"#,
    ]);
    assert_eq!(r[1], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(r[2]["Messages"][0]["ReceiveCount"], 1);
    assert_eq!(r[4]["Messages"][0]["ReceiveCount"], 2);
    assert_eq!(r[4]["Messages"][0]["FirstReceivedAt"], 0);
    assert_eq!(r[5]["error"]["code"], "ReceiptHandleExpired");
    assert_eq!(r[6]["error"]["code"], "ReceiptHandleInvalid");
    assert_eq!(r[7], json!({"ok": true}));
}

#[test]
fn fifo_deduplicates_within_window_only() {
    let send = r#"{"Command":"SendMessage","QueueName":"q.fifo","Body":"b","GroupId":"g"}"#;
    let tick = |s| format!(r#"{{"Command":"Tick","Seconds":{s}}}"#);
    let (t299, t1) = (tick(299), tick(1));
    let r = run(&[
        r#"{"Command":"CreateQueue","QueueName":"q.fifo","Attributes":{"Fifo":true,"ContentBasedDeduplication":true}}"#,
        send, &t299, send, &t1, send,
    ]);
    assert_eq!(r[1], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(r[3], r[1]);
    assert_eq!(r[5], json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
}

#[test]
fn dead_letter_move_resets_the_message() {
    let r = run(&[
        r#"{"Command":"CreateQueue","QueueName":"dlq"}"#,
        r#"{"Command":"CreateQueue","QueueName":"q","Attributes":{"VisibilityTimeout":0,"DeadLetterQueue":"dlq","MaxReceiveCount":1}}"#,
        r#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"q"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"q"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"dlq"}"#,
    ]);
    assert_eq!(r[3]["Messages"].as_array().unwrap().len(), 1);
    assert_eq!(r[4]["Messages"], json!([]));
    assert_eq!(r[5]["Messages"][0]["MessageId"], "m-1");
    assert_eq!(r[5]["Messages"][0]["ReceiveCount"], 1);
}

#[test]
fn retention_removes_messages_and_counts_states() {
    let r = run(&[
        r#"{"Command":"CreateQueue","QueueName":"q","Attributes":{"RetentionSeconds":60}}"#,
        r#"{"Command":"SendMessage","QueueName":"q","Body":"a","DelaySeconds":30}"#,
        r#"{"Command":"GetQueueAttributes","QueueName":"q"}"#,
        r#"{"Command":"Tick","Seconds":60}"#,
        r#"{"Command":"GetQueueAttributes","QueueName":"q"}"#,
    ]);
    assert_eq!(r[2]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 1}));
    assert_eq!(r[4]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn list_queues_sorts_by_bytes() {
    let r = run(&[
        r#"{"Command":"CreateQueue","QueueName":"b"}"#,
        r#"{"Command":"CreateQueue","QueueName":"B"}"#,
        r#"{"Command":"CreateQueue","QueueName":"_"}"#,
        r#"{"Command":"ListQueues"}"#,
    ]);
    assert_eq!(r[3]["QueueNames"], json!(["B", "_", "b"]));
}
EOF
cargo test 2>&1 | grep -E "^error|panicked|test result|left|right" | head -20

